"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { DataTable } from "@/components/ui/data-table";
import { Dialog } from "@/components/ui/dialog";
import { EmptyState } from "@/components/ui/empty-state";
import { SelectField, TextField } from "@/components/ui/form-controls";
import { NavTabs } from "@/components/ui/nav-tabs";
import { PageHeader } from "@/components/ui/page-header";
import { CompactSelect } from "@/components/ui/compact-select";
import styles from "../routes/routes.module.css";

type Type = "DRIVER" | "PARTNER" | "TEMP_VEHICLE" | "CUSTOMER";
const labels: Record<Type, string> = { DRIVER: "司机工资", PARTNER: "合作车账单", TEMP_VEHICLE: "临时车账单", CUSTOMER: "客户对账单" };
const statusLabel: Record<string, string> = { DRAFT: "草稿", PENDING_CONFIRMATION: "待确认", CONFIRMED: "已确认", ADJUSTED: "已调整", VOIDED: "已作废", UNPAID: "未结算", PARTIALLY_PAID: "部分结算", PAID: "已结清", REVERSED: "已冲销" };
const confirmationChoices = (status: string) => status === "DRAFT" ? ["DRAFT", "PENDING_CONFIRMATION"] : status === "PENDING_CONFIRMATION" ? ["PENDING_CONFIRMATION", "CONFIRMED"] : [status];
const paymentChoices = ["UNPAID", "PARTIALLY_PAID", "PAID", "REVERSED"];
function monthNow() { return new Date().toISOString().slice(0, 7); }
const years = Array.from({ length: 11 }, (_, index) => String(new Date().getFullYear() - 5 + index));
async function request(url: string, method = "GET", body?: unknown) { const res = await fetch(url, { method, headers: body ? { "content-type": "application/json" } : undefined, body: body ? JSON.stringify(body) : undefined }); const json = await res.json(); if (!res.ok) throw new Error(json.error || "操作失败"); return json; }

export function SettlementBillsClient({ initialBills, options }: any) {
  const router = useRouter(); const [tab, setTab] = useState<Type>("DRIVER"), [objectFilter, setObjectFilter] = useState(""), [monthFilter, setMonthFilter] = useState(""), [creating, setCreating] = useState(false), [notice, setNotice] = useState(""), [year, setYear] = useState(() => monthNow().slice(0, 4)), [month, setMonth] = useState(() => monthNow().slice(5, 7));
  const filterField = tab === "DRIVER" ? "driverId" : tab === "CUSTOMER" ? "customerId" : undefined;
  const settlementMonths = useMemo(() => [...new Set<string>(initialBills.filter((bill: any) => bill.billType === tab).map((bill: any) => bill.settlementMonth))].sort((a, b) => b.localeCompare(a)), [initialBills, tab]);
  const rows = useMemo(() => initialBills.filter((b: any) => b.billType === tab && (!filterField || !objectFilter || b[filterField] === objectFilter) && (!monthFilter || b.settlementMonth === monthFilter)), [initialBills, tab, filterField, objectFilter, monthFilter]);
  async function create(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const f = new FormData(event.currentTarget); try { const bill = await request("/api/finance/bills", "POST", { billType: tab, settlementMonth: f.get("month"), settlementObjectId: f.get("objectId") }); setCreating(false); setNotice(`已创建 ${bill.billNo}。请从待结算明细加入已完成的运输段。`); router.refresh(); } catch (e) { setNotice(e instanceof Error ? e.message : "创建失败"); } }
  async function change(id: string, patch: { confirmationStatus?: string; paymentStatus?: string }) { try { await request(`/api/finance/bills/${id}`, "PATCH", patch); router.refresh(); } catch (e) { setNotice(e instanceof Error ? e.message : "更新失败"); } }
  return <main><PageHeader title="账单管理" actions={<Button onClick={() => setCreating(true)}>新增{labels[tab]}</Button>} /><NavTabs label="账单类别" items={(Object.keys(labels) as Type[]).map(type => ({ label: labels[type], active: tab === type, onClick: () => { setTab(type); setObjectFilter(""); setMonthFilter(""); } }))} /><div className={styles.toolbar}>{filterField && <SelectField label={tab === "DRIVER" ? "筛选司机" : "筛选客户"} className={styles.customerSelect} value={objectFilter} onChange={event => setObjectFilter(event.target.value)}><option value="">{tab === "DRIVER" ? "全部司机" : "全部客户"}</option>{(options[tab] || []).map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</SelectField>}<SelectField label="结算月份" className={styles.customerSelect} value={monthFilter} onChange={event => setMonthFilter(event.target.value)}><option value="">全部月份</option>{settlementMonths.map(value => <option key={value} value={value}>{value}</option>)}</SelectField></div>{notice && <p role="status">{notice}</p>}{rows.length ? <DataTable><thead><tr><th>账单编号</th><th>结算对象</th><th>结算月份</th><th>明细</th><th>金额</th><th>对账</th><th>收付款</th></tr></thead><tbody>{rows.map((bill: any) => <tr key={bill.id}><td><a href={`/finance/bills/${bill.id}`}><b>{bill.billNo}</b></a></td><td>{bill.driver?.name || bill.fleetOwner?.name || bill.vehicle?.plateNumber || bill.customer?.name}</td><td>{bill.settlementMonth}</td><td>{bill._count.lines}</td><td>¥ {bill.totalAmount}</td><td><CompactSelect aria-label="修改对账状态" value={bill.confirmationStatus} disabled={bill.confirmationStatus === "CONFIRMED" || bill.confirmationStatus === "VOIDED"} onChange={event => change(bill.id, { confirmationStatus: event.target.value })}>{confirmationChoices(bill.confirmationStatus).map(status => <option key={status} value={status}>{statusLabel[status]}</option>)}</CompactSelect></td><td><CompactSelect aria-label="修改收付款状态" value={bill.paymentStatus} onChange={event => change(bill.id, { paymentStatus: event.target.value })}>{paymentChoices.map(status => <option key={status} value={status}>{statusLabel[status]}</option>)}</CompactSelect></td></tr>)}</tbody></DataTable> : <EmptyState title={`暂无${labels[tab]}`}>创建账单后，从待结算明细添加已完成运输段；未配置价格不会按零元入账。</EmptyState>}{creating && <Dialog title={`新增${labels[tab]}`} onClose={() => setCreating(false)} actions={<><Button variant="secondary" onClick={() => setCreating(false)}>取消</Button><Button type="submit" form="bill-form">创建草稿</Button></>}><form id="bill-form" className={styles.form} onSubmit={create}><div className={styles.monthPicker}><input type="hidden" name="month" value={`${year}-${month}`} /><div className={styles.monthPickerControls}><SelectField label="年份" value={year} onChange={event => setYear(event.target.value)}>{years.map(value => <option key={value} value={value}>{value}年</option>)}</SelectField><SelectField label="月份" value={month} onChange={event => setMonth(event.target.value)}>{Array.from({ length: 12 }, (_, index) => String(index + 1).padStart(2, "0")).map(value => <option key={value} value={value}>{Number(value)}月</option>)}</SelectField></div></div><SelectField label={tab === "DRIVER" ? "司机" : tab === "PARTNER" ? "合作车老板" : tab === "TEMP_VEHICLE" ? "临时车" : "客户"} name="objectId" required>{(options[tab] || []).map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</SelectField></form></Dialog>}</main>;
}
